"""Facts about this turn for the system prompt's Environment block: where the agent works and what will ask first.

Everything here is read from the database (never from the model or a tool result) and is short, so it costs a few dozen
tokens. Nothing is started to find it out: a sandbox that does not exist yet is described as such, not created.
"""
import logging
from uuid import UUID

from sqlalchemy import select

from agentforge.database.delivery import ConversationDelivery
from agentforge.database.models import Task
from agentforge.database.sessions import Conversation, TurnExecution
from agentforge.integrations.e2b_sandbox import WORKSPACE
from agentforge.tools.approvals import get_mode
from agentforge.tools.catalog import ASKS_BEFORE

log = logging.getLogger(__name__)
WORKSPACE_TOOLS = frozenset({"bash", "read", "write", "edit", "grep", "find", "ls"})


def delivery_description(delivery: ConversationDelivery) -> str | None:
    """One short line on where this conversation's work stands on GitHub, or None if nothing has been published or is waiting."""
    pr, waiting = delivery.pr_json or {}, delivery.unpublished_json
    parts = []
    if delivery.branch and delivery.head_sha:
        parts.append(f"published to branch {delivery.branch}")
    if delivery.pr_number:
        checks = pr.get("checks") or {}
        detail = [pr.get("state") or "open"]
        if checks.get("state") in {"failing", "pending", "passing"}:
            detail.append(f"checks {checks['state']}" + (f" ({checks.get('failed')} failed)" if checks.get("failed") else ""))
        if pr.get("mergeable") == "conflicting":
            detail.append("merge conflicts")
        if (pr.get("reviews") or {}).get("decision") == "changes_requested":
            detail.append("changes requested")
        parts.append(f"pull request #{delivery.pr_number} ({', '.join(detail)}); get_pr_status shows the checks")
    if waiting:
        parts.append(f"{waiting.get('files', 0)} changed files are not pushed yet")
    if not parts:
        return None
    return ("; ".join(parts) + ". create_pull_request adds a commit to that branch and pull request (it never opens a second one). "
            "The person merges from the Changes panel; you cannot.")


def turn_environment(sessions, *, task_id: UUID, user_id: UUID, tools: tuple[str, ...]) -> dict[str, str]:
    """Labelled facts, in the order they are shown. Sync: call it in a thread."""
    with sessions() as db:
        grants = db.scalar(select(Task.permissions_json).where(Task.id == task_id)) or {}
        sandbox_id = db.scalar(select(Conversation.sandbox_id).join(TurnExecution, TurnExecution.session_id == Conversation.id)
                               .where(TurnExecution.task_id == task_id))
        try:
            delivery = db.scalar(select(ConversationDelivery).join(TurnExecution, TurnExecution.session_id == ConversationDelivery.conversation_id)
                                 .where(TurnExecution.task_id == task_id, ConversationDelivery.status == "active"))
            delivery_fact = delivery_description(delivery) if delivery is not None else None
        except Exception:
            # An extra line of context must never cost the turn its whole environment block (e.g. a database not yet migrated).
            db.rollback()
            log.warning("delivery facts unavailable: task_id=%s", task_id, exc_info=True)
            delivery_fact = None
    facts: dict[str, str] = {}
    if WORKSPACE_TOOLS & set(tools):
        facts["Workspace"] = (f"{WORKSPACE}, a persistent Linux sandbox. " + (
            "It was started in an earlier turn, so files and changes from earlier turns should still be there."
            if sandbox_id else "Not started yet; it starts on the first workspace call."))
    if grants.get("attachments") and WORKSPACE_TOOLS & set(tools):
        from agentforge.integrations.attachment_storage import workspace_attachment_path
        facts["Attached files"] = "Available after the first workspace call: " + "; ".join(
            workspace_attachment_path(task_id, index, item["name"]) for index, item in enumerate(grants["attachments"]))
    repository = grants.get("repository") or {}
    if repository.get("repo_id"):
        ref = str(repository.get("ref") or "")
        facts["Repository"] = repository["repo_id"] + (f" at commit {ref[:12]}" if ref else "") + (
            ", checked out at the workspace root (base tag agentforge-base)" if WORKSPACE_TOOLS & set(tools) else "")
    if delivery_fact and "create_pull_request" in tools:
        facts["GitHub delivery"] = delivery_fact
    plugins: dict[str, int] = {}
    for name in tools:
        if "__" in name:
            plugins[name.split("__", 1)[0]] = plugins.get(name.split("__", 1)[0], 0) + 1
    if plugins:
        facts["Plugins"] = ", ".join(f"{slug} ({count} tool{'s' if count != 1 else ''})" for slug, count in plugins.items())
    asking = sorted(ASKS_BEFORE & set(tools)) + (["plugin tools that change something"] if plugins else [])
    if asking:
        facts["Approvals"] = ("Ask me: " + ", ".join(asking) + " wait for the person's approval before they run."
                              if get_mode(sessions, user_id) == "ask" else "Approve for me: nothing waits for approval.")
    return facts
"""What a skill is, and the rules every skill (built in or written by a person) must meet before it can be saved or offered.

A skill is a name, a one-paragraph description and a body of instructions, written as a `SKILL.md` file:

    ---
    name: code-review
    description: Review code changes and report prioritized findings. Use when asked to review a diff or pull request.
    ---
    # Code review
    ...

The description is the only thing the agent sees before it decides to load a skill, so it must say what the skill does and when to use
it. The instructions are loaded in one tool result, so their size is bounded by what that result can carry.
"""
import json
import re
from dataclasses import dataclass

NAME_PATTERN = re.compile(r"^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$")
NAME_MIN, NAME_MAX = 3, 40
DESCRIPTION_MIN, DESCRIPTION_MAX = 10, 300
INSTRUCTIONS_MIN, INSTRUCTIONS_MAX = 20, 10_000
# A tool result must stay under 16,000 bytes as JSON (see tools/gateway.py); the instructions are most of it. Counted as JSON text, so
# newlines and quotes (two bytes each once escaped) count for what they cost.
INSTRUCTIONS_JSON_BYTES = 13_000


class SkillInvalid(ValueError):
    """A skill that cannot be saved: the field at fault and a sentence a person can act on."""

    def __init__(self, field: str, message: str) -> None:
        super().__init__(message)
        self.field, self.message = field, message


@dataclass(frozen=True)
class SkillDocument:
    name: str
    description: str
    instructions: str


def clean_name(value: object) -> str:
    name = value.strip() if isinstance(value, str) else ""
    if not NAME_MIN <= len(name) <= NAME_MAX or not NAME_PATTERN.fullmatch(name):
        raise SkillInvalid("name", f"The name must be {NAME_MIN}-{NAME_MAX} characters: lowercase letters, digits and single hyphens, "
                                    "starting with a letter (for example review-contract).")
    return name


def clean_description(value: object) -> str:
    """One line of printable text: a description that runs over several lines is joined."""
    text = " ".join("".join(char if char.isprintable() or char in "\n\t" else " " for char in value).split()) if isinstance(value, str) else ""
    if not DESCRIPTION_MIN <= len(text) <= DESCRIPTION_MAX:
        raise SkillInvalid("description", f"The description must be {DESCRIPTION_MIN}-{DESCRIPTION_MAX} characters. Say what the skill does "
                                          "and when to use it: it is all the agent sees before it decides to load the skill.")
    return text


def clean_instructions(value: object) -> str:
    """Instructions with line endings normalized and control characters removed, or SkillInvalid."""
    if not isinstance(value, str):
        raise SkillInvalid("instructions", "Write the instructions the agent should follow.")
    text = value.replace("\r\n", "\n").replace("\r", "\n")
    text = "".join(char for char in text if char in "\n\t" or char.isprintable())
    text = "\n".join(line.rstrip() for line in text.split("\n")).strip("\n")
    text = re.sub(r"\n{4,}", "\n\n\n", text)
    if not INSTRUCTIONS_MIN <= len(text.strip()) <= INSTRUCTIONS_MAX:
        raise SkillInvalid("instructions", f"The instructions must be {INSTRUCTIONS_MIN}-{INSTRUCTIONS_MAX:,} characters.")
    if len(json.dumps(text, ensure_ascii=False).encode("utf-8")) > INSTRUCTIONS_JSON_BYTES:
        raise SkillInvalid("instructions", "The instructions are too long once saved (many quotes, line breaks or non-English characters take more "
                                           "room). Shorten them.")
    return text


def validated(name: object, description: object, instructions: object) -> SkillDocument:
    return SkillDocument(clean_name(name), clean_description(description), clean_instructions(instructions))


def parse_skill_markdown(source: str) -> SkillDocument:
    """A `SKILL.md` (front matter with name and description, then the instructions) as a validated skill. Raises SkillInvalid."""
    text = source.replace("\r\n", "\n").replace("\r", "\n").lstrip("﻿")
    lines = text.split("\n")
    if not lines or lines[0].strip() != "---":
        raise SkillInvalid("instructions", "A SKILL.md starts with a line of three dashes, then name: and description:, then three dashes.")
    try:
        end = next(index for index in range(1, len(lines)) if lines[index].strip() == "---")
    except StopIteration:
        raise SkillInvalid("instructions", "The front matter is not closed with a line of three dashes.") from None
    fields: dict[str, str] = {}
    for line in lines[1:end]:
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        key, separator, value = line.partition(":")
        if not separator or key != key.strip() or not key:
            raise SkillInvalid("instructions", f"The front matter line “{line.strip()[:60]}” is not in the form key: value.")
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
            value = value[1:-1]
        fields[key.strip().lower()] = value
    return validated(fields.get("name"), fields.get("description"), "\n".join(lines[end + 1:]))


def format_skill_markdown(skill: SkillDocument) -> str:
    """The `SKILL.md` text of a skill, which parse_skill_markdown reads back."""
    return f"---\nname: {skill.name}\ndescription: {skill.description}\n---\n{skill.instructions}\n"

